CREATE TEMP TABLE lit_modules ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"slug":"introduction-to-literature","code":"GUIDE_SSS1_LIT_T1_INTRO","name":"Introduction to Literature","body":"# Introduction to Literature — SSS1 Literature in English, First Term\n\n## Learning intentions\nBy the end of the lesson, you should explain literature as artistic expression, identify the purposes of literary works, distinguish a text''s message from an unsupported personal claim, and give reasons for studying literature in Nigeria and elsewhere.\n\n## What is literature?\nLiterature is creative expression through spoken or written language. A literary text invites readers or listeners to imagine, feel, question and interpret human experience. **Prose**, **poetry** and **drama** are major literary genres. Oral storytelling, songs, riddles and praise poetry are also important parts of literary culture; literature did not begin when people started printing books.\n\nConsider an original sentence: *The village bell had spoken, yet no one opened a door.* Its literal meaning is that the bell rang and doors remained closed. A reader might infer fear, secrecy or a warning, but the reason must be supported by the surrounding narrative. An inference is a reasoned interpretation, not a fact the text explicitly states.\n\n## Functions of literature\nA literary work can entertain, preserve collective memories, explore moral questions, criticise injustice, celebrate identity and deepen empathy for unfamiliar experiences. Different readers may disagree about the moral of a story; useful classroom discussion explains **which words or events** support each interpretation.\n\n## Literary versus purely informational writing\nA bus timetable communicates departure times; a story about a missed bus may use setting, tension, voice and characters to explore disappointment and resilience. The same everyday subject can be represented as a fictional event, a poem, a scene in a play or a plain report. Literary texts often use imagery, character development and deliberate word choice, although factual writing can be creative too.\n\n## Reading for meaning\nOn a first reading, identify who is speaking, what happens, where events occur and which questions remain unanswered. On a second reading, underline significant words and notice repeated images or oppositions. Then form a claim, include an exact detail and explain how that detail supports the claim. Avoid replacing analysis with retelling.\n\n**Original mini-text:** *Amina carried the library key through the rain. She had promised her classmates that the books would be safe.* A reasonable claim is that Amina values responsibility. Evidence: she keeps the key despite the rain and remembers her promise. The rain also creates a challenge without requiring a long plot.\n\n## Nigerian and global contexts\nOral narratives, modern Nigerian prose, African poetry and stage plays all offer valuable perspectives. Respect regional languages, translations and culturally distinct performance styles. Do not assume that one narrator represents every member of a community.\n\n## Learner activity\nChoose a familiar folktale and describe its narrator, conflict, setting and central idea without copying a summary. Then rewrite one event as a brief news report. Compare the purposes and styles of the two versions.\n\n## Check understanding\n1. Name three literary genres. **Prose, poetry and drama.**\n2. What is a textual inference? **An interpretation supported by clues.**\n3. Why cite details? **To make your interpretation defensible.**\n\n## Common errors\nTreating all literature as printed fiction, confusing entertainment with literature''s only purpose, or asserting a theme without evidence. In assessment, distinguish what the text says from what you infer.","cards":[{"front":"Name three major literary genres.","back":"Prose, poetry and drama.","difficulty":"medium","sourceKind":"original-literature"},{"front":"Can literature exist orally?","back":"Yes. Folktales, riddles, songs and praise poetry are forms of oral literature.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is a textual inference?","back":"An interpretation supported by details rather than stated outright.","difficulty":"medium","sourceKind":"original-literature"},{"front":"Name two functions of literature.","back":"For example: entertainment, social criticism, cultural memory or empathy.","difficulty":"medium","sourceKind":"original-literature"},{"front":"How should an interpretation be supported?","back":"Use a specific textual detail and explain the link to the claim.","difficulty":"medium","sourceKind":"original-literature"},{"front":"How is a timetable unlike a literary story?","back":"A timetable mainly reports factual times, while a story can develop characters, conflict and imagery.","difficulty":"medium","sourceKind":"original-literature"}],"questions":[{"question":"Which description best captures literature as a subject?","options":[{"id":"A","text":"Creative verbal expression exploring human experience"},{"id":"B","text":"Only lists of facts"},{"id":"C","text":"Only printed fictional books"},{"id":"D","text":"Only old plays"}],"answer":"A","explanation":"Literature uses spoken or written language creatively to represent and examine human experiences."},{"question":"A folktale recited to children belongs to:","options":[{"id":"A","text":"Only scientific writing"},{"id":"B","text":"Oral literature"},{"id":"C","text":"Only legal reporting"},{"id":"D","text":"Only a printed bibliography"}],"answer":"B","explanation":"Oral literature is transmitted through spoken performance, not necessarily through a book."},{"question":"Which is an important function of literary writing?","options":[{"id":"A","text":"Guaranteeing a reader one correct opinion"},{"id":"B","text":"Replacing every news report"},{"id":"C","text":"Exploring moral and social questions"},{"id":"D","text":"Providing only public timetables"}],"answer":"C","explanation":"Literature can raise questions about human values and society while allowing reasoned interpretations."},{"question":"The claim ''Amina is responsible'' is strongest when it includes:","options":[{"id":"A","text":"The reader''s favourite author"},{"id":"B","text":"A guess about an unrelated character"},{"id":"C","text":"A claim without details"},{"id":"D","text":"Details about her promise and protecting the key"}],"answer":"D","explanation":"Textual evidence makes the interpretation testable against the story."},{"question":"Which statement is a reasonable definition of an inference?","options":[{"id":"A","text":"An interpretation drawn from textual clues"},{"id":"B","text":"A line explicitly quoted with no interpretation"},{"id":"C","text":"An unsupported guess"},{"id":"D","text":"A statement that cannot be questioned"}],"answer":"A","explanation":"Inferences go beyond an exact statement but must be supported by evidence."},{"question":"Which of these is usually a literary genre?","options":[{"id":"A","text":"Train schedule"},{"id":"B","text":"Drama"},{"id":"C","text":"Stock inventory"},{"id":"D","text":"School attendance register"}],"answer":"B","explanation":"Drama is a major genre written or performed through characters'' actions and speech."},{"question":"What should follow a claim in a literary paragraph?","options":[{"id":"A","text":"A second unrelated claim"},{"id":"B","text":"A copied conclusion without analysis"},{"id":"C","text":"Relevant textual evidence and explanation"},{"id":"D","text":"A demand that all readers agree"}],"answer":"C","explanation":"A claim becomes persuasive when a detail is explained rather than merely named."},{"question":"Which is a common mistake in literary analysis?","options":[{"id":"A","text":"Quoting brief relevant evidence"},{"id":"B","text":"Comparing interpretations"},{"id":"C","text":"Noticing repeated images"},{"id":"D","text":"Retelling events without explaining their significance"}],"answer":"D","explanation":"Plot summary alone does not analyse theme, technique or meaning."},{"question":"A short story about a missed bus differs from a timetable because it can:","options":[{"id":"A","text":"Explore characters and conflict"},{"id":"B","text":"Provide only departure times"},{"id":"C","text":"Have no narrator or events"},{"id":"D","text":"Avoid all language choices"}],"answer":"A","explanation":"Narrative writing may explore character reactions and develop conflict rather than merely list factual times."},{"question":"Why might readers interpret a scene differently?","options":[{"id":"A","text":"Textual evidence is always irrelevant"},{"id":"B","text":"They may emphasise different supported textual clues"},{"id":"C","text":"Every inference is automatically true"},{"id":"D","text":"No text can support any interpretation"}],"answer":"B","explanation":"Interpretations can vary while still being evaluated against specific textual details."},{"question":"Which is an example of a literature study activity?","options":[{"id":"A","text":"Copying only page numbers"},{"id":"B","text":"Memorising a book''s price"},{"id":"C","text":"Explaining how the setting intensifies conflict"},{"id":"D","text":"Counting desks in a classroom"}],"answer":"C","explanation":"Analysing how setting shapes conflict examines the effect of a literary technique."},{"question":"An oral praise poem chiefly demonstrates that literature:","options":[{"id":"A","text":"Must always be a novel"},{"id":"B","text":"Cannot contain history"},{"id":"C","text":"Has no artistic language"},{"id":"D","text":"Can be performed and culturally transmitted"}],"answer":"D","explanation":"Performance, rhythm and imagery make oral forms part of literary traditions."}]},{"slug":"literary-appreciation","code":"GUIDE_SSS1_LIT_T1_APPRECIATION","name":"Literary Appreciation","body":"# Literary Appreciation — SSS1 Literature in English, First Term\n\n## Learning aims\nLearn to identify a literary work''s theme, plot, setting, characterisation, tone, mood and style. More importantly, explain **how a specific detail creates an effect**, instead of simply naming a literary term.\n\n## A useful reading approach\nBegin with the literal situation. Who is speaking or acting? What is the conflict? Then examine the writer''s choices and the reader''s likely response. Good appreciation links the three stages: **observation → evidence → interpretation**.\n\n## Plot and conflict\nPlot is the purposeful arrangement of events. A story may introduce a situation, develop a difficulty, reach a turning point and move towards a resolution. An unresolved ending is also possible. Conflict may occur between characters, within one person''s thoughts or between a character and circumstances. Conflict need not be violent.\n\n**Original mini-story:** *Tari wanted to return the lost purse. Her friends argued that the money could pay for their school trip. She waited at the empty gate, then walked to the owner''s shop.* The central conflict is a choice between an ethical responsibility and peer pressure. The action of returning the purse contributes to characterisation.\n\n## Theme versus subject\nA **subject** is what a text is about in broad terms, such as friendship. A **theme** is an idea the text develops about that subject, such as ''Friendship is tested when private gain competes with honesty.'' Themes are better expressed as meaningful propositions than single abstract words. Avoid imposing a theme that the text cannot support.\n\n## Setting and characterisation\nSetting includes time, place and social circumstances. A market closing during a storm can produce urgency or isolation. **Characterisation** is how writers reveal a person through choices, dialogue, actions, thoughts and responses from others. A character who carefully returns borrowed items may be presented as dependable, but look for more than one clue before making large claims.\n\n## Tone, mood and style\n**Tone** is the attitude suggested by a narrator''s or speaker''s language, such as amused, bitter or hopeful. **Mood** is the atmosphere experienced by the audience, such as tense or peaceful. **Style** is the manner of expression: sentence rhythm, imagery, diction, viewpoint and structure. The tone can be calm while a scene''s mood remains anxious.\n\n## A worked appreciation paragraph\nOriginal extract: *The lantern flickered three times. Bisi tightened her grip on the letter but continued through the corridor.*\n\n**Claim:** The setting creates a tense mood. **Evidence:** The unstable lantern and dark corridor make Bisi''s route uncertain. **Explanation:** The light''s repeated flickering suggests insecurity, while Bisi''s continued movement hints at determination. That is stronger than simply saying ''the passage is interesting''.\n\n## Comparison practice\nDescribe the difference between these original lines:\n*The garden slept beneath gentle rain* and *Rain battered the empty garden wall*. Both contain rain, but the verbs ''slept'' and ''battered'' suggest different moods. Analyse wording before deciding.\n\n## Self-assessment\nState the subject and one plausible theme of the Tari story; identify one action revealing her character; distinguish tone from mood. Always include an exact supporting clue.\n\n## Common errors\nReducing theme to a single noun, assuming a narrator equals the author, confusing plot with a chronological list of everything, or naming ''imagery'' without discussing the effect.","cards":[{"front":"What is plot?","back":"The purposeful arrangement of events in a narrative or drama.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is theme?","back":"An idea or insight developed by a text; not just a one-word subject.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is setting?","back":"Time, location and social circumstances of events.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is characterisation?","back":"How a writer reveals character through actions, speech, thoughts and reactions.","difficulty":"medium","sourceKind":"original-literature"},{"front":"Differentiate tone and mood.","back":"Tone is the voice''s attitude; mood is the atmosphere felt by an audience.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is evidence-based appreciation?","back":"A claim supported by textual details and an explanation of their effect.","difficulty":"medium","sourceKind":"original-literature"}],"questions":[{"question":"A story''s purposeful sequence of events is its:","options":[{"id":"A","text":"Plot"},{"id":"B","text":"Mood"},{"id":"C","text":"Diction"},{"id":"D","text":"Meter"}],"answer":"A","explanation":"Plot organises incidents, conflicts and turning points into a meaningful progression."},{"question":"Which states a theme more precisely than a subject?","options":[{"id":"A","text":"Honesty"},{"id":"B","text":"Honesty can demand courage under peer pressure"},{"id":"C","text":"A person"},{"id":"D","text":"School bags"}],"answer":"B","explanation":"A theme expresses a developed idea rather than simply identifying a general subject."},{"question":"The time and place of a story form part of its:","options":[{"id":"A","text":"Rhyme scheme"},{"id":"B","text":"Cast list"},{"id":"C","text":"Setting"},{"id":"D","text":"Metaphor only"}],"answer":"C","explanation":"Setting includes time, place and surrounding social conditions."},{"question":"A character returning a found purse is an example of characterisation through:","options":[{"id":"A","text":"Rhyme"},{"id":"B","text":"Footnote"},{"id":"C","text":"Stage equipment"},{"id":"D","text":"Action"}],"answer":"D","explanation":"An ethical decision shown through action supplies evidence about a character."},{"question":"Which most directly describes mood?","options":[{"id":"A","text":"The anxious atmosphere felt by a reader"},{"id":"B","text":"The author''s passport details"},{"id":"C","text":"The printing date"},{"id":"D","text":"A character''s full name"}],"answer":"A","explanation":"Mood is the atmosphere or feeling the scene evokes in an audience."},{"question":"In a passage, tone is usually inferred from:","options":[{"id":"A","text":"The book''s size alone"},{"id":"B","text":"The speaker''s language and attitude"},{"id":"C","text":"The number of pages"},{"id":"D","text":"The classroom temperature"}],"answer":"B","explanation":"Word choice and voice reveal attitudes such as affection, irony, hostility or hope."},{"question":"''The lantern flickered'' in a dark corridor could produce:","options":[{"id":"A","text":"An automatic joyful atmosphere"},{"id":"B","text":"A guaranteed factual date"},{"id":"C","text":"A tense mood"},{"id":"D","text":"An exact rhyme scheme"}],"answer":"C","explanation":"Uncertain light and restricted visibility can build suspense."},{"question":"How should a learner support a claim about character?","options":[{"id":"A","text":"Assert the claim twice"},{"id":"B","text":"Ignore the actual passage"},{"id":"C","text":"Use only the writer''s biography"},{"id":"D","text":"Refer to a revealing action or line of dialogue"}],"answer":"D","explanation":"Direct details from the text justify character interpretation."},{"question":"Which sentence concerns style?","options":[{"id":"A","text":"The writer uses short sentences to quicken the pace"},{"id":"B","text":"The novel is in a schoolbag"},{"id":"C","text":"The pages are stapled"},{"id":"D","text":"The library has a gate"}],"answer":"A","explanation":"Style includes sentence choices, rhythm, imagery, diction and structural technique."},{"question":"Which pair correctly matches the terms?","options":[{"id":"A","text":"Tone: page number; mood: year"},{"id":"B","text":"Tone: attitude; mood: atmosphere"},{"id":"C","text":"Tone: plot; mood: protagonist"},{"id":"D","text":"Tone: genre; mood: author"}],"answer":"B","explanation":"Tone describes the voice''s attitude and mood describes the emotional effect on readers."},{"question":"In literary study, conflict can be:","options":[{"id":"A","text":"Only physical fighting"},{"id":"B","text":"Only a printed dialogue"},{"id":"C","text":"Internal or external"},{"id":"D","text":"Only one character''s age"}],"answer":"C","explanation":"Conflict may involve opposing people, values, social forces or a character''s own thoughts."},{"question":"A strong analysis of an image should explain:","options":[{"id":"A","text":"Only how many letters it has"},{"id":"B","text":"Only whether the word is long"},{"id":"C","text":"Only who printed the book"},{"id":"D","text":"How its wording shapes meaning and effect"}],"answer":"D","explanation":"Interpretation explains the image''s function rather than merely identifying it."}]},{"slug":"literary-devices-one","code":"GUIDE_SSS1_LIT_T1_DEV1","name":"Literary Devices I: Simile, Metaphor, Irony, Personification and Oxymoron","body":"# Literary Devices I — SSS1 Literature in English, First Term\n\n## Objectives\nDistinguish simile, metaphor, irony, personification and oxymoron; interpret original examples; and explain why a writer might prefer an image to a literal description.\n\n## Simile and metaphor\nA **simile** compares unlike things explicitly, usually with ''like'' or ''as'': *The queue curled like a river through the courtyard.* The comparison suggests a winding shape. A **metaphor** identifies one thing with another directly: *The queue was a river of restless feet.* The literal queue is not water; the expression represents movement and length.\n\nDo not assume that every occurrence of ''like'' forms a simile. *I like mangoes* expresses preference, not a comparison. A metaphor can extend across several lines, but each additional image should remain meaningful.\n\n## Personification\n**Personification** gives human qualities to non-human things: *The old gate groaned when the wind arrived.* A gate does not literally express suffering; the human-like groan makes its creaking sound vivid. Personification differs from a scene featuring an actual human.\n\n## Irony\nIrony can involve a contrast between what is expected and what actually happens, or between the literal words and a speaker''s intended meaning. For example, after a sudden downpour ruins a picnic, a character says, *What wonderful weather!* The context suggests verbal irony. A scene where a fire station catches fire may suggest situational irony. Irony should be inferred from context, not from a word alone.\n\n## Oxymoron\nAn **oxymoron** joins apparently contradictory terms, such as *deafening silence* or *bittersweet reunion*, to express complexity or tension. It is not any pair of different words: *small room* is not a contradiction.\n\n## Worked reading task\nOriginal extract: *Morning swallowed the last streetlamp. The market was a restless ocean; traders appeared like birds returning to a tree. “Such a quiet place,” Musa whispered above the shouting.*\n\nThe streetlamp line personifies morning. ''Restless ocean'' is a metaphor suggesting the market''s movement and scale. The bird comparison is a simile. Musa''s reference to quietness may be verbally ironic given the shouting.\n\n## Structure a response\nWhen identifying a device, quote just the phrase needed, name the device, explain the comparison or contrast and describe its effect. For example: *''The market was a restless ocean'' is a metaphor that emphasises its size and constant movement*. This method earns more understanding than listing five device names.\n\n## Practice and feedback\nWrite one original simile about rain, one metaphor about time, and one personification of a school bell. Explain the literal reality behind each expression. A plausible response is *''The rain tapped like fingers on the roof''* — a simile based on sound.\n\n## Common errors\nCalling every ''as'' a simile, treating irony as any unfortunate event, or identifying oxymoron without explaining the contrast. Avoid reciting definitions with no examples.","cards":[{"front":"What is a simile?","back":"An explicit comparison, typically using like or as.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is a metaphor?","back":"A direct figurative identification or comparison.","difficulty":"medium","sourceKind":"original-literature"},{"front":"Define personification.","back":"Giving human traits or actions to non-human things.","difficulty":"medium","sourceKind":"original-literature"},{"front":"Define oxymoron.","back":"A compact pairing of apparently contradictory terms.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What may create verbal irony?","back":"A contrast between literal words and intended meaning in context.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What makes device analysis complete?","back":"Identify a short example and explain its meaning and effect.","difficulty":"medium","sourceKind":"original-literature"}],"questions":[{"question":"''The queue curled like a river'' is a:","options":[{"id":"A","text":"Simile"},{"id":"B","text":"Oxymoron"},{"id":"C","text":"Dramatic irony"},{"id":"D","text":"Allusion"}],"answer":"A","explanation":"The phrase makes an explicit comparison using ''like''."},{"question":"''The market was an ocean'' is a:","options":[{"id":"A","text":"Literal geography statement"},{"id":"B","text":"Metaphor"},{"id":"C","text":"Euphemism"},{"id":"D","text":"Rhyme scheme"}],"answer":"B","explanation":"The market is directly identified with an ocean to suggest movement and scale."},{"question":"''The gate groaned'' illustrates:","options":[{"id":"A","text":"Hyperbole only"},{"id":"B","text":"Stage direction"},{"id":"C","text":"Personification"},{"id":"D","text":"Assonance only"}],"answer":"C","explanation":"A non-human gate receives a human-like action."},{"question":"''Deafening silence'' is an example of:","options":[{"id":"A","text":"Understatement"},{"id":"B","text":"Plot"},{"id":"C","text":"Dialogue"},{"id":"D","text":"Oxymoron"}],"answer":"D","explanation":"Opposing ideas of loudness and silence are compressed into one phrase."},{"question":"When a character says ''Wonderful weather'' during a disastrous storm, it may be:","options":[{"id":"A","text":"Verbal irony"},{"id":"B","text":"An exact factual forecast"},{"id":"C","text":"A compulsory simile"},{"id":"D","text":"A rhyme"}],"answer":"A","explanation":"The speaker''s intended message contrasts with the literal wording and storm context."},{"question":"Which statement is literal rather than a simile?","options":[{"id":"A","text":"The child ran like lightning"},{"id":"B","text":"I like mangoes"},{"id":"C","text":"Her voice was as gentle as rain"},{"id":"D","text":"The bus moved like a snail"}],"answer":"B","explanation":"Here ''like'' expresses preference, not similarity between two things."},{"question":"The main effect of personifying a noisy door as ''angry'' is to:","options":[{"id":"A","text":"Prove the door can think"},{"id":"B","text":"State its manufacturing year"},{"id":"C","text":"Make its sound vivid"},{"id":"D","text":"Reveal the author''s name"}],"answer":"C","explanation":"Personification connects a physical sound to human emotion for vivid expression."},{"question":"Situational irony typically involves:","options":[{"id":"A","text":"Always two words that rhyme"},{"id":"B","text":"A list of settings"},{"id":"C","text":"Only line breaks"},{"id":"D","text":"An outcome contrasting with an expected result"}],"answer":"D","explanation":"Situational irony is grounded in an unexpected reversal of circumstances."},{"question":"Which is NOT an oxymoron?","options":[{"id":"A","text":"Small room"},{"id":"B","text":"Bittersweet memory"},{"id":"C","text":"Deafening silence"},{"id":"D","text":"Living dead"}],"answer":"A","explanation":"A small room is an ordinary descriptive phrase, not a meaningful contradiction."},{"question":"Why must a writer use context to identify irony?","options":[{"id":"A","text":"Every sentence contains irony"},{"id":"B","text":"The intended meaning may differ from literal words"},{"id":"C","text":"Irony can only occur in prose"},{"id":"D","text":"Context has no role in meaning"}],"answer":"B","explanation":"Without situational or vocal clues, apparent praise could be genuine rather than ironic."},{"question":"Which sentence contains personification?","options":[{"id":"A","text":"The roof is made of zinc"},{"id":"B","text":"It rained at noon"},{"id":"C","text":"The rain argued with the roof"},{"id":"D","text":"A man spoke beneath the roof"}],"answer":"C","explanation":"Rain is described as arguing, an action normally associated with people."},{"question":"A good answer to a literary-device question should:","options":[{"id":"A","text":"List the device only"},{"id":"B","text":"Describe the book cover"},{"id":"C","text":"Invent evidence absent from the line"},{"id":"D","text":"Name the device and explain its effect"}],"answer":"D","explanation":"Marks for analysis depend on explaining how figurative language shapes meaning."}]},{"slug":"literary-devices-two","code":"GUIDE_SSS1_LIT_T1_DEV2","name":"Literary Devices II: Sound, Contrast and Allusion","body":"# Literary Devices II: Sound, Contrast and Allusion — SSS1 First Term\n\n## Learning objectives\nRecognise alliteration, assonance, repetition, hyperbole, euphemism, allusion and paradox, then analyse each device using short original examples.\n\n## Alliteration and assonance\n**Alliteration** repeats initial consonant sounds in nearby words: *Busy builders balanced beams.* What matters is sound, not the mere repetition of a written letter. **Assonance** repeats vowel sounds in nearby words: *The slow road rolled home.* Sound patterns can produce musicality, emphasis or a deliberate mood; they do not automatically make a passage cheerful.\n\n## Repetition\n**Repetition** deliberately reuses a word, phrase or structure for emphasis or rhythm. Original example: *We will listen. We will learn. We will lead.* The repeated ''We will'' gives the line a collective, determined rhythm. In assessment, identify what is repeated and explain the effect.\n\n## Hyperbole and euphemism\n**Hyperbole** is deliberate exaggeration for effect: *I have waited a thousand years for this bus.* The speaker does not mean a literal thousand years. **Euphemism** substitutes a milder expression for an uncomfortable or harsh one: *He passed away* instead of *He died*. A euphemism can reveal politeness, discomfort or avoidance; it should not obscure critical facts in serious reporting.\n\n## Allusion\nAn **allusion** is a brief reference to a known person, work, story or event without retelling it fully. A line comparing a difficult journey to an ''Odyssey'' may allude to a famous narrative of travel. Because audiences have different background knowledge, explain the reference rather than assuming everyone recognises it.\n\n## Paradox\nA **paradox** appears self-contradictory but can express an insight: *The more answers I memorised without understanding, the less prepared I felt.* The apparent contradiction distinguishes knowledge from rote recall. An oxymoron is usually a short pair of contradictory terms, while a paradox may be expressed across a whole statement.\n\n## Guided reading\nOriginal extract: *Bright birds broke the bitter silence. We waited, waited and waited; I thought the clock would never move. At last the headteacher said the visitors had passed away.*\n\nAlliteration occurs in ''Bright birds broke'' (repeated initial /b/). ''Waited'' is repetition; ''the clock would never move'' may be a hyperbolic expression of impatience. ''Passed away'' is euphemistic language describing death. Consider which interpretations are supported by the story context, not merely by the words alone.\n\n## Comparison\n''Soft silence'' may contain repeated initial /s/ sounds but is not automatically an oxymoron; both ideas are compatible. ''A cheerful tragedy'' can contain conflicting ideas, depending on how a writer uses the phrase. Literary labels should follow meaning as well as form.\n\n## Try independently\nWrite a line of alliteration using a market setting. Create one respectful euphemism, one deliberate exaggeration and one paradox about studying. Then exchange explanations with a classmate: which are literal and which depend on shared context?\n\n## Common errors\nConfusing repeated initial sounds with repeated vowel sounds, calling an ordinary large number hyperbole, or identifying an allusion without knowing the referenced story.","cards":[{"front":"What is alliteration?","back":"Repeated initial consonant sounds in nearby words.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is assonance?","back":"Repeated vowel sounds in nearby words.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is hyperbole?","back":"Deliberate exaggeration for emphasis.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is euphemism?","back":"A milder expression substituted for a harsher or uncomfortable one.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is allusion?","back":"A brief indirect reference to a known work, person, event or story.","difficulty":"medium","sourceKind":"original-literature"},{"front":"How does paradox differ from oxymoron?","back":"A paradox is a seemingly contradictory statement; oxymoron is usually a short juxtaposition of opposing terms.","difficulty":"medium","sourceKind":"original-literature"}],"questions":[{"question":"''Busy builders balanced beams'' illustrates:","options":[{"id":"A","text":"Alliteration"},{"id":"B","text":"Oxymoron"},{"id":"C","text":"Understatement"},{"id":"D","text":"Euphemism"}],"answer":"A","explanation":"The nearby words repeat the initial consonant /b/ sound."},{"question":"Repeated vowel sounds within neighbouring words create:","options":[{"id":"A","text":"End rhyme only"},{"id":"B","text":"Assonance"},{"id":"C","text":"Flashback"},{"id":"D","text":"Soliloquy"}],"answer":"B","explanation":"Assonance is a pattern of recurring vowel sounds, regardless of exact spelling."},{"question":"''I have waited a thousand years'' in a short queue is likely:","options":[{"id":"A","text":"A literal age record"},{"id":"B","text":"A precise scientific measurement"},{"id":"C","text":"Hyperbole"},{"id":"D","text":"An example of stage design"}],"answer":"C","explanation":"The deliberate exaggeration emphasises how long the wait feels."},{"question":"''Passed away'' instead of ''died'' is a:","options":[{"id":"A","text":"Metaphor only"},{"id":"B","text":"Stage whisper"},{"id":"C","text":"Footnote"},{"id":"D","text":"Euphemism"}],"answer":"D","explanation":"It replaces direct harsh wording with a gentler expression."},{"question":"A brief mention of a widely known myth without retelling it is:","options":[{"id":"A","text":"Allusion"},{"id":"B","text":"Denouement"},{"id":"C","text":"Script instruction"},{"id":"D","text":"Personification only"}],"answer":"A","explanation":"Allusion gains meaning by invoking an external story or cultural reference."},{"question":"''We will listen. We will learn. We will lead'' uses:","options":[{"id":"A","text":"A single simile"},{"id":"B","text":"Repetition"},{"id":"C","text":"An unrelated acronym"},{"id":"D","text":"Dialogue alone"}],"answer":"B","explanation":"The repeated phrase ''We will'' creates rhythmic emphasis and collective purpose."},{"question":"Which best defines paradox?","options":[{"id":"A","text":"A pair of rhyming words"},{"id":"B","text":"Any incorrect mathematical equation"},{"id":"C","text":"A seemingly contradictory claim that may reveal an insight"},{"id":"D","text":"A play''s character list"}],"answer":"C","explanation":"Paradox presents apparent contradiction that invites deeper interpretation."},{"question":"Which is closest to oxymoron rather than a full paradox?","options":[{"id":"A","text":"The more I hurried, the later I arrived"},{"id":"B","text":"Effort can make a person wiser"},{"id":"C","text":"Studying takes time"},{"id":"D","text":"Bittersweet victory"}],"answer":"D","explanation":"Opposite qualities are compressed into the short expression ''bittersweet''."},{"question":"The most reliable basis for identifying alliteration is:","options":[{"id":"A","text":"Repeated beginning consonant sounds"},{"id":"B","text":"Identical last letters"},{"id":"C","text":"A character name"},{"id":"D","text":"The number of paragraphs"}],"answer":"A","explanation":"Alliteration is based on sound patterns, not simply visual spelling."},{"question":"Why should an allusion be explained in class?","options":[{"id":"A","text":"Every allusion is a direct quotation"},{"id":"B","text":"Some readers may not recognise the referenced story"},{"id":"C","text":"It has no interpretive significance"},{"id":"D","text":"It always names a book''s price"}],"answer":"B","explanation":"An explanation clarifies the borrowed association and its contribution to meaning."},{"question":"Which example is an obvious hyperbole?","options":[{"id":"A","text":"The bag has two books"},{"id":"B","text":"The student bought a notebook"},{"id":"C","text":"My schoolbag weighs a mountain"},{"id":"D","text":"The bag is on a table"}],"answer":"C","explanation":"The claim is impossible literally, and exaggeration conveys an emotional sense of weight."},{"question":"A repeated phrase in an appeal can chiefly create:","options":[{"id":"A","text":"A new author identity"},{"id":"B","text":"A guaranteed plot resolution"},{"id":"C","text":"An exact publication year"},{"id":"D","text":"Emphasis and rhythm"}],"answer":"D","explanation":"Purposeful repetition can reinforce an idea and organise spoken rhythm."}]},{"slug":"three-literary-genres","code":"GUIDE_SSS1_LIT_T1_GENRES","name":"The Three Literary Genres","body":"# The Three Literary Genres — SSS1 Literature in English, First Term\n\n## Objectives\nCompare prose, poetry and drama through their usual structures, purposes and reading conventions. Recognise that a writer can blend techniques without changing the dominant genre.\n\n## Prose\n**Prose** uses sentences and paragraphs rather than a regular metrical pattern. Stories, novellas and novels are common forms of prose fiction. Prose can present a narrator''s account, extended description and character dialogue. Chapters organise longer works, but a short story may contain no chapters at all.\n\nOriginal prose extract: *The bus arrived late. Nnenna folded her timetable and looked towards the clinic. She would have to decide whether to wait or walk.* The account includes characters, setting, a possible conflict and narrative time.\n\n## Poetry\n**Poetry** often pays close attention to rhythm, line, imagery, sound and compressed meaning. A poem may use stanzas; a stanza is a group of lines. Poetry does not always rhyme, and free verse does not have to follow a fixed metrical scheme.\n\nOriginal lines:\n*Across the roof the first rain falls;*\n*The dusty yard remembers green.*\n\nThe two lines employ imagery and personification. They can also be read without a narrator giving a full series of events.\n\n## Drama\n**Drama** is literature designed to be performed or imagined through characters speaking and acting. A script includes dialogue, characters'' names and may give stage directions. Longer plays may be divided into acts and scenes.\n\nOriginal dramatic excerpt:\n**ADA:** The gate is still open.\n**KOLA:** Then we have a choice.\n*(Ada looks towards the road.)*\n\nThe bracketed description is a stage direction, not dialogue. Dialogue tells the audience what characters say, while stage directions guide action, movement or performance.\n\n## Cross-genre techniques\nAll three genres can explore theme, conflict, character and setting. A poem may tell a story, a play may contain poetic speech, and prose may use rhythm. Genre is chiefly identified by the text''s dominant structural form and presentation, not by the subject discussed.\n\n| Form | Common organisation | Characteristic mode |\n|---|---|---|\n| Prose | Sentences, paragraphs, sometimes chapters | Narration and description |\n| Poetry | Lines and often stanzas | Condensed, patterned language |\n| Drama | Dialogue, scenes and directions | Enacted speech and action |\n\n## Guided comparison\nWrite about a market closing, first as a three-sentence prose narrative, then as four lines of poetry, and finally as a short dialogue involving two traders. Consider what each form communicates efficiently and what the reader must infer.\n\n## Check understanding\nIdentify why ''Act II, Scene I'' suggests drama; explain why an unrhymed poem remains poetry; name two ways a novella differs in scale from a novel without assuming an exact compulsory word count.\n\n## Common errors\nDefining poetry only by rhyme, thinking plays cannot be read, or claiming all prose must be fiction. Genre labels describe broad traditions, not inflexible rules.","cards":[{"front":"Three major genres?","back":"Prose, poetry and drama.","difficulty":"medium","sourceKind":"original-literature"},{"front":"Common structural unit in prose?","back":"Paragraphs; longer prose may use chapters.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is a stanza?","back":"A grouped set of poetic lines.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is a stage direction?","back":"A script instruction for action, movement or performance.","difficulty":"medium","sourceKind":"original-literature"},{"front":"Must poetry rhyme?","back":"No. Free verse may have no fixed rhyme scheme.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What dominates drama?","back":"Characters'' dialogue and enacted actions.","difficulty":"medium","sourceKind":"original-literature"}],"questions":[{"question":"A long narrative organised into paragraphs and chapters is commonly:","options":[{"id":"A","text":"Prose"},{"id":"B","text":"A stage cue"},{"id":"C","text":"A single chorus"},{"id":"D","text":"A rhyme scheme"}],"answer":"A","explanation":"Prose normally uses paragraphs and may divide an extended narrative into chapters."},{"question":"A group of poetic lines is a:","options":[{"id":"A","text":"Cast"},{"id":"B","text":"Stanza"},{"id":"C","text":"Act"},{"id":"D","text":"Footnote"}],"answer":"B","explanation":"A stanza is a group of lines forming a structural unit in a poem."},{"question":"The notation ''(She exits)'' in a play is a:","options":[{"id":"A","text":"Narrator''s metaphor"},{"id":"B","text":"Verse foot"},{"id":"C","text":"Stage direction"},{"id":"D","text":"Genre title"}],"answer":"C","explanation":"Stage directions give performance guidance rather than spoken dialogue."},{"question":"Which statement about poetry is correct?","options":[{"id":"A","text":"Every poem must rhyme"},{"id":"B","text":"Every poem must be 14 lines"},{"id":"C","text":"Poetry contains no imagery"},{"id":"D","text":"Poetry can use free verse without a fixed rhyme scheme"}],"answer":"D","explanation":"Rhyme and fixed metre are not universal requirements for poetry."},{"question":"Drama is primarily presented through:","options":[{"id":"A","text":"Characters'' speech and actions"},{"id":"B","text":"Only a narrator''s essay"},{"id":"C","text":"Financial tables"},{"id":"D","text":"Rhyme schemes without characters"}],"answer":"A","explanation":"Dialogue and action form the central means of presentation in most drama."},{"question":"A novella is most closely related to which genre?","options":[{"id":"A","text":"Only lyric poetry"},{"id":"B","text":"Prose fiction"},{"id":"C","text":"Only stage lighting"},{"id":"D","text":"Only oral music"}],"answer":"B","explanation":"A novella is a prose-fiction form, typically shorter than a novel."},{"question":"Which is usually a stage script feature?","options":[{"id":"A","text":"A map legend"},{"id":"B","text":"Only numbered laboratory results"},{"id":"C","text":"Named speakers before lines of dialogue"},{"id":"D","text":"Only book chapters"}],"answer":"C","explanation":"Character names identify who delivers each line in drama."},{"question":"Which can appear in prose, poetry and drama?","options":[{"id":"A","text":"Only stanza breaks"},{"id":"B","text":"Only a cast list"},{"id":"C","text":"Only act numbers"},{"id":"D","text":"Theme"}],"answer":"D","explanation":"Every major genre can explore themes, even though their structural conventions differ."},{"question":"An unrhymed poem is still poetry because:","options":[{"id":"A","text":"Poetry need not use end rhyme"},{"id":"B","text":"It becomes prose automatically"},{"id":"C","text":"It must become drama"},{"id":"D","text":"It cannot use metaphor"}],"answer":"A","explanation":"Poetic form can depend on lines, rhythm, image and compression without rhyme."},{"question":"''Act II, Scene I'' is most associated with:","options":[{"id":"A","text":"A newspaper headline"},{"id":"B","text":"Drama"},{"id":"C","text":"A prose glossary"},{"id":"D","text":"A pie chart"}],"answer":"B","explanation":"Acts and scenes are conventional structural divisions for stage plays."},{"question":"A paragraph of a narrator describing a bus journey best fits:","options":[{"id":"A","text":"A stage direction only"},{"id":"B","text":"A soliloquy automatically"},{"id":"C","text":"Prose"},{"id":"D","text":"A haiku necessarily"}],"answer":"C","explanation":"Connected narrative sentences in paragraphs are a characteristic prose form."},{"question":"A text combining storytelling and imagery should be classified mainly by:","options":[{"id":"A","text":"Only its first word"},{"id":"B","text":"Only the author''s age"},{"id":"C","text":"The number of characters mentioned"},{"id":"D","text":"Its dominant structure and presentation"}],"answer":"D","explanation":"Genres overlap in techniques, so dominant form determines the main classification."}]},{"slug":"understanding-prose-fiction","code":"GUIDE_SSS1_LIT_T1_PROSE","name":"Understanding Prose Fiction","body":"# Understanding Prose Fiction — SSS1 Literature in English, First Term\n\n## Learning aims\nIdentify narrator, viewpoint, plot, conflict, setting and character development, and explain how evidence supports an interpretation of prose fiction.\n\n## Narrative voice\nA **first-person narrator** tells a story using ''I'' or ''we'' and is limited by what they witness or know. A **third-person narrator** uses names and pronouns such as ''she'' and ''they''. Third-person narration may closely follow one character''s thoughts or describe multiple viewpoints. A narrator is the voice telling the story, not automatically the writer.\n\nOriginal first-person extract: *I kept the invitation hidden until Friday because I feared my brother''s reaction.* Readers understand the narrator''s fear but cannot assume they know the brother''s private thoughts.\n\n## Plot development\nA narrative often introduces a situation, sets a problem in motion, intensifies conflict, reaches a turning point and arrives at a resolution or open ending. A **flashback** interrupts the present narrative to show an earlier event. It is important to identify what information the earlier scene adds.\n\n## Character and motivation\nA character may desire something, face obstacles and change decisions as events unfold. **Direct characterisation** states a quality, such as ''Musa was generous''; **indirect characterisation** demonstrates it through speech or conduct, such as Musa sharing his last meal. Strong answers cite actions and consequences.\n\n## Original model passage\n*On Monday, Zainab found the missing register beside the locked storeroom. She remembered arguing with Idris on Friday. He had promised to return the register, but the key lay under a mat. She placed the book on the headteacher''s desk without writing an accusation.*\n\nQuestions: What is the present narrative time? Monday. What earlier event is remembered? The Friday argument. What does Zainab''s refusal to accuse suggest? Carefulness, restraint or uncertainty—but not proof of Idris''s innocence or guilt. What is one unresolved question? Who moved the register.\n\n## Showing versus telling\nA line such as *''He was afraid''* states an emotion directly. *''He checked the door latch for the third time''* may show unease indirectly. Both methods are useful; discuss the impact of the writer''s choice.\n\n## Themes and context\nLook for repeated decisions, contrasting outcomes and pressures shaping the characters. A character''s silence could indicate fear, respect, deceit or uncertainty; select interpretations supported by nearby details. Avoid reading outside stereotypes into a text simply because it takes place in a particular Nigerian city or community.\n\n## Short writing task\nWrite a 150-word original story involving a misplaced letter, a conflict over trust and an ending that leaves one question unanswered. Mark one sentence as direct and another as indirect characterisation. Exchange stories and test whether a reader can infer a theme from real evidence.\n\n## Common mistakes\nEquating narrator with author, assuming a flashback is any memory mentioned, confusing plot summary with analysis, and declaring a character guilty without textual grounds.","cards":[{"front":"What is first-person narration?","back":"Storytelling through ''I'' or ''we'' from a narrator''s perspective.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is third-person narration?","back":"Storytelling about characters using names and pronouns such as she, he or they.","difficulty":"medium","sourceKind":"original-literature"},{"front":"Define flashback.","back":"A shift to earlier events within a later narrative point.","difficulty":"medium","sourceKind":"original-literature"},{"front":"Direct versus indirect characterisation?","back":"Direct tells qualities; indirect shows qualities through actions, dialogue and behaviour.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is conflict in prose?","back":"An opposition or difficulty that drives character choices and events.","difficulty":"medium","sourceKind":"original-literature"},{"front":"Why is narrator not automatically author?","back":"The narrator is a constructed storytelling voice and may differ from the real writer.","difficulty":"medium","sourceKind":"original-literature"}],"questions":[{"question":"A story narrated using ''I'' typically uses:","options":[{"id":"A","text":"First-person narration"},{"id":"B","text":"Only a stage chorus"},{"id":"C","text":"Third-person omniscience automatically"},{"id":"D","text":"A camera caption"}],"answer":"A","explanation":"The pronoun ''I'' usually marks a character-narrator recounting events."},{"question":"What is a flashback?","options":[{"id":"A","text":"A chronological ending"},{"id":"B","text":"A return to earlier events within a narrative"},{"id":"C","text":"A scene that never happened"},{"id":"D","text":"A book''s foreword"}],"answer":"B","explanation":"Flashbacks shift narrative time backward to provide relevant prior context."},{"question":"''Musa shared his last meal'' demonstrates character through:","options":[{"id":"A","text":"Only a direct adjective"},{"id":"B","text":"Publication details"},{"id":"C","text":"Action"},{"id":"D","text":"Rhyme"}],"answer":"C","explanation":"Sharing food demonstrates generosity indirectly rather than simply labelling Musa generous."},{"question":"The narrator is best described as:","options":[{"id":"A","text":"Always the writer as a real-life person"},{"id":"B","text":"Always the villain"},{"id":"C","text":"Only the publisher"},{"id":"D","text":"The voice presenting a story"}],"answer":"D","explanation":"Narrators are storytelling voices that may be distinct from their authors."},{"question":"Which describes indirect characterisation?","options":[{"id":"A","text":"Showing a quality through decisions and dialogue"},{"id":"B","text":"Writing ''She was brave'' only"},{"id":"C","text":"Naming the book''s printer"},{"id":"D","text":"Listing a date"}],"answer":"A","explanation":"Readers infer traits from what characters do and say."},{"question":"An unresolved question at the end of a story creates:","options":[{"id":"A","text":"A guaranteed happy resolution"},{"id":"B","text":"An open ending"},{"id":"C","text":"A glossary"},{"id":"D","text":"A stanza"}],"answer":"B","explanation":"Open endings deliberately leave outcomes or explanations unsettled."},{"question":"The physical and social circumstances of the plot are part of the:","options":[{"id":"A","text":"Meter"},{"id":"B","text":"Rhyme"},{"id":"C","text":"Setting"},{"id":"D","text":"Cast of actors only"}],"answer":"C","explanation":"Setting includes where and when events happen and the social conditions surrounding them."},{"question":"A third-person narrator usually refers to people using:","options":[{"id":"A","text":"Only I"},{"id":"B","text":"Only we"},{"id":"C","text":"Only you"},{"id":"D","text":"He, she, they or character names"}],"answer":"D","explanation":"Third-person narration primarily uses third-person references to characters."},{"question":"A story''s conflict is:","options":[{"id":"A","text":"The central opposition or problem"},{"id":"B","text":"Its total number of pages"},{"id":"C","text":"Its publisher''s address"},{"id":"D","text":"Any adjective"}],"answer":"A","explanation":"Opposing goals or difficulties generate decisions and propel plot events."},{"question":"''He checked the door latch again'' may imply anxiety through:","options":[{"id":"A","text":"Direct definition only"},{"id":"B","text":"Indirect characterisation"},{"id":"C","text":"A rhyme scheme"},{"id":"D","text":"A book review"}],"answer":"B","explanation":"Repeated protective action provides a clue to emotion without stating it."},{"question":"A strong claim about a character''s guilt needs:","options":[{"id":"A","text":"A stereotype about the setting"},{"id":"B","text":"Only an accusation by another character"},{"id":"C","text":"Supporting textual evidence"},{"id":"D","text":"No reference to the story"}],"answer":"C","explanation":"An accusation in dialogue is not automatically confirmed by the narrator or events."},{"question":"Which question is most useful for prose analysis?","options":[{"id":"A","text":"How many staplers are in the room?"},{"id":"B","text":"What colour is my school uniform?"},{"id":"C","text":"What is the book''s price?"},{"id":"D","text":"How do the character''s choices develop the conflict?"}],"answer":"D","explanation":"Linking decisions with conflict reveals how narrative elements work together."}]},{"slug":"introduction-to-drama","code":"GUIDE_SSS1_LIT_T1_DRAMA","name":"Drama: Characters, Dialogue and Stagecraft","body":"# Drama: Characters, Dialogue and Stagecraft — SSS1 First Term\n\n## Objectives\nRead a play script fluently, distinguish dialogue from stage directions, analyse dramatic conflict and describe the roles of actors, scenes, stage setting and an audience.\n\n## Drama as written and performed literature\nA play is often designed for performance. **Dialogue** is conversation between characters; a **monologue** is an extended speech by one character; a **soliloquy** traditionally presents a character''s private thoughts as spoken alone or as if alone. An **aside** is a remark conventionally heard by the audience but not by other characters onstage.\n\nLonger plays may be organised into acts and scenes, though modern drama does not always follow fixed divisions. The **cast** comprises performers or named characters, depending on context; the **playwright** writes the play and the **director** guides its performance.\n\n## Stage directions\nStage directions describe movement, gesture, position, lighting, sound or expression. They are not spoken as dialogue unless a production deliberately chooses to reinterpret them. Props are movable objects actors use, such as an umbrella; stage setting includes the environment represented.\n\n## Original mini-scene\n**AMAKA:** You said the community hall would be open.\n\n**FEMI:** It was open yesterday.\n\n*(A distant bell rings. Amaka holds up a wet notice.)*\n\n**AMAKA:** Then read today''s announcement.\n\n**FEMI** *(aside):* I knew the repairs would delay us.\n\n**AMAKA:** What did you say?\n\n**FEMI:** Nothing. We should find another venue.\n\nThis short scene builds conflict around unreliable information and a blocked plan. The bell may create urgency; the wet notice is a prop and possible evidence. The aside gives the audience information that Amaka may lack, which can produce dramatic irony if the gap matters.\n\n## Dramatic conflict and action\nPlays reveal motives not only through what characters say but also through pauses, gestures and entrances or exits. A speaker who says ''Nothing'' after admitting a secret in an aside reveals a contrast between public speech and private intention.\n\n## Types of drama\n**Comedy** frequently explores humour and misunderstanding, though it need not have a happy ending in every modern example. **Tragedy** often examines serious conflict and suffering. **Tragicomedy** combines elements of both. Classify a whole play with evidence, not from a single funny line or sad incident.\n\n## Staging exercise\nIn pairs, perform the mini-scene twice: first with the bell loud and urgent, then with the bell soft and distant. Note changes in tension. Explain one stage direction and its effect without rewriting it as dialogue.\n\n## Independent checks\nIdentify the characters, one prop, one stage direction and one conflict in the scene. What does the aside reveal? What does Amaka know? Keep these perspectives separate.\n\n## Common errors\nCalling a narrator''s paragraph dialogue, confusing an aside with a soliloquy, assuming the director authored the play, and attributing every stage detail to character speech.","cards":[{"front":"What is dialogue?","back":"Spoken conversation between characters in a play.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is a stage direction?","back":"An instruction for movement, expression, lighting, sound or action.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is an aside?","back":"A remark to the audience not conventionally heard by other onstage characters.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is a soliloquy?","back":"A speech revealing a character''s thoughts while alone or as if alone.","difficulty":"medium","sourceKind":"original-literature"},{"front":"Who writes a play?","back":"A playwright.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is a prop?","back":"A movable object used onstage by an actor.","difficulty":"medium","sourceKind":"original-literature"}],"questions":[{"question":"A conversation between characters in a play is:","options":[{"id":"A","text":"Dialogue"},{"id":"B","text":"A bibliography"},{"id":"C","text":"A narrative footnote"},{"id":"D","text":"Meter"}],"answer":"A","explanation":"Dialogue is the exchange of spoken lines among characters."},{"question":"''(A bell rings)'' in a script is:","options":[{"id":"A","text":"Spoken dialogue"},{"id":"B","text":"Stage direction"},{"id":"C","text":"A rhyme scheme"},{"id":"D","text":"A chapter heading"}],"answer":"B","explanation":"The bracketed note tells performers or production staff about a sound cue."},{"question":"A character''s brief remark to the audience, unnoticed by others onstage, is:","options":[{"id":"A","text":"Epilogue"},{"id":"B","text":"Stanza"},{"id":"C","text":"Aside"},{"id":"D","text":"Essay"}],"answer":"C","explanation":"An aside conventionally shares information with the audience while excluding other characters."},{"question":"A speech expressing a character''s private thoughts alone is a:","options":[{"id":"A","text":"Duet"},{"id":"B","text":"Stage prop"},{"id":"C","text":"Cast list"},{"id":"D","text":"Soliloquy"}],"answer":"D","explanation":"A soliloquy reveals inner thoughts through speech delivered alone or as if alone."},{"question":"The creator of a play''s written script is the:","options":[{"id":"A","text":"Playwright"},{"id":"B","text":"Stage electrician necessarily"},{"id":"C","text":"Ticket seller"},{"id":"D","text":"Publisher only"}],"answer":"A","explanation":"Playwright is the name for a dramatist who writes a play."},{"question":"A letter held by an actor onstage is a:","options":[{"id":"A","text":"Rhyme"},{"id":"B","text":"Prop"},{"id":"C","text":"Stanza"},{"id":"D","text":"Act"}],"answer":"B","explanation":"Props are objects handled or used during a performance."},{"question":"In the mini-scene, the wet notice can function as:","options":[{"id":"A","text":"A narrator''s footnote"},{"id":"B","text":"A verse meter"},{"id":"C","text":"A prop and potential evidence"},{"id":"D","text":"A genre"}],"answer":"C","explanation":"The physical notice can be handled on stage and may carry information supporting the conflict."},{"question":"A play divided into Act I and Act II uses:","options":[{"id":"A","text":"Only prose chapters"},{"id":"B","text":"Only couplets"},{"id":"C","text":"A map key"},{"id":"D","text":"Dramatic structural divisions"}],"answer":"D","explanation":"Acts and scenes conventionally organise play action and performance."},{"question":"Which feature can reveal dramatic character?","options":[{"id":"A","text":"A pause before answering"},{"id":"B","text":"Only page count"},{"id":"C","text":"Only book price"},{"id":"D","text":"Only seating capacity"}],"answer":"A","explanation":"A purposeful pause can communicate uncertainty or concealment to an audience."},{"question":"A story combining comic elements with serious suffering may be:","options":[{"id":"A","text":"A factual timetable"},{"id":"B","text":"Tragicomedy"},{"id":"C","text":"A dictionary entry"},{"id":"D","text":"Only lyric verse"}],"answer":"B","explanation":"Tragicomedy blends aspects of comic and tragic drama."},{"question":"Which is an example of stagecraft rather than spoken dialogue?","options":[{"id":"A","text":"A character saying ''Come back''"},{"id":"B","text":"Two characters arguing"},{"id":"C","text":"Lighting fading as a character exits"},{"id":"D","text":"A character answering a question"}],"answer":"C","explanation":"Stagecraft concerns how visual, sonic and movement choices present the play."},{"question":"Who typically coordinates actors'' performance choices in a production?","options":[{"id":"A","text":"Narrator only"},{"id":"B","text":"Audience only"},{"id":"C","text":"Typesetter only"},{"id":"D","text":"Director"}],"answer":"D","explanation":"A director helps shape staging, movement and interpretation during production."}]},{"slug":"introduction-to-poetry","code":"GUIDE_SSS1_LIT_T1_POETRY","name":"Poetry: Imagery, Voice and Form","body":"# Poetry: Imagery, Voice and Form — SSS1 First Term\n\n## Objectives\nDistinguish a poem''s speaker from its author; identify lines, stanzas, image, rhythm, rhyme and free verse; explain how sound and diction contribute to meaning.\n\n## The speaker\nA poem''s **speaker** is the voice heard within it, not necessarily the poet''s real-life self. When a voice says ''I'', inspect the rest of the poem before deciding who is speaking. A dramatic speaker may be an imagined child, traveller, elder or non-human object.\n\n## Lines and stanzas\nA **line** is a basic visual and rhythmic unit in many poems; a **stanza** groups lines. A couplet has two lines and a quatrain has four, although labels describe forms rather than guarantee a fixed theme. A line break can create a pause, focus attention or delay the completion of a thought.\n\n## Imagery\n**Imagery** uses language to engage sensory experience—sight, sound, touch, taste or smell. *''The smoke scratched my throat''* appeals to sensation and can also imply physical discomfort. Images become more useful when tied to a theme or a speaker''s feeling.\n\n## Rhythm and rhyme\nRhythm is an audible pattern of stresses, syllables, pauses and phrasing. **Rhyme** involves matching sounds, often near the end of lines. **Free verse** does not follow a fixed conventional metrical or rhyme scheme; it can still be deliberately rhythmic.\n\n## Original example poem\n*At dawn the market lifts its eyes,*\n*And red dust climbs the waking sky.*\n*One shutter waits, one lantern swings;*\n*The road remembers yesterday.*\n\nThis original four-line poem uses personification: a market ''lifts its eyes'' and a road ''remembers''. Visual imagery includes dawn and red dust. A reader might see renewal mixed with a memory of earlier difficulty, but that interpretation should be explained rather than imposed.\n\n## Speaker, tone and mood\nA speaker can sound hopeful, weary, skeptical or celebratory. Tone is the attitude conveyed by diction and voice; mood is the atmosphere experienced by readers. An image of dawn often suggests a beginning but can also signal a difficult day''s work, depending on context.\n\n## Another original example\n*I counted every passing light*\n*Until the town was out of sight.*\n\nThe last words ''light'' and ''sight'' rhyme. The image of departing lights may suggest travel, separation or relief; what follows will constrain a final interpretation.\n\n## Reading procedure\nRead once for literal meaning, once aloud to notice sound, and once to connect images, perspective and overall idea. Identify one phrase as evidence and explain what the phrase does. Do not assign a conventional rhyme scheme to lines that do not actually rhyme.\n\n## Create and assess\nCompose four original lines on a school morning. Include an image that appeals to hearing and one meaningful line break. Underline the speaker''s words that reveal tone. Peer-review whether a reader can identify the intended atmosphere.\n\n## Common errors\nAssuming all poetry rhymes, treating the poetic ''I'' as verified autobiography, defining imagery only as ''pictures'', or naming rhyme without considering emotional effect.","cards":[{"front":"What is the speaker of a poem?","back":"The voice heard within the poem, not necessarily the poet.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is a stanza?","back":"A grouping of poetic lines.","difficulty":"medium","sourceKind":"original-literature"},{"front":"Define imagery.","back":"Language that evokes sensory experience.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is free verse?","back":"Poetry without a fixed conventional meter or rhyme scheme.","difficulty":"medium","sourceKind":"original-literature"},{"front":"How is rhyme recognised?","back":"By matching sounds, often at line endings.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is a quatrain?","back":"A four-line stanza.","difficulty":"medium","sourceKind":"original-literature"}],"questions":[{"question":"The ''I'' in a poem is most accurately called:","options":[{"id":"A","text":"Speaker"},{"id":"B","text":"Always the poet''s literal autobiography"},{"id":"C","text":"Publisher"},{"id":"D","text":"Stage director"}],"answer":"A","explanation":"A poetic speaker is a constructed voice and may differ from the poet."},{"question":"A stanza of four lines is called a:","options":[{"id":"A","text":"Couplet"},{"id":"B","text":"Quatrain"},{"id":"C","text":"Novel"},{"id":"D","text":"Cast"}],"answer":"B","explanation":"A quatrain consists of four poetic lines grouped as one stanza."},{"question":"Poetic language appealing to smell and sound exemplifies:","options":[{"id":"A","text":"A chapter heading"},{"id":"B","text":"Only a cast list"},{"id":"C","text":"Imagery"},{"id":"D","text":"A page index"}],"answer":"C","explanation":"Imagery invokes sensory experience beyond sight alone."},{"question":"Free verse is poetry that:","options":[{"id":"A","text":"Cannot have rhythm"},{"id":"B","text":"Always rhymes AABB"},{"id":"C","text":"Must be 14 lines"},{"id":"D","text":"Does not obey a fixed traditional metre or rhyme scheme"}],"answer":"D","explanation":"Free verse may have rhythm and sound patterns while avoiding fixed formal schemes."},{"question":"Which pair of words has end rhyme?","options":[{"id":"A","text":"Light and sight"},{"id":"B","text":"Moon and tree"},{"id":"C","text":"Road and sand"},{"id":"D","text":"Stone and cloud"}],"answer":"A","explanation":"Light and sight share a matching final sound."},{"question":"''The road remembers yesterday'' uses:","options":[{"id":"A","text":"A literal claim about a road''s brain"},{"id":"B","text":"Personification"},{"id":"C","text":"A stage direction"},{"id":"D","text":"Scientific reporting"}],"answer":"B","explanation":"The non-human road is given the human capacity to remember."},{"question":"A two-line stanza is a:","options":[{"id":"A","text":"Quatrain"},{"id":"B","text":"Act"},{"id":"C","text":"Couplet"},{"id":"D","text":"Paragraph"}],"answer":"C","explanation":"A couplet is a pair of poetic lines that may or may not rhyme."},{"question":"Rhythm in poetry may arise from:","options":[{"id":"A","text":"Only the book price"},{"id":"B","text":"Only page size"},{"id":"C","text":"Only the writer''s hometown"},{"id":"D","text":"Stress, pause and phrasing"}],"answer":"D","explanation":"Rhythmic movement comes from sound and timing choices."},{"question":"What is a careful way to analyse a line break?","options":[{"id":"A","text":"Explain how it changes emphasis or suspense"},{"id":"B","text":"Count it as a genre by itself"},{"id":"C","text":"Ignore surrounding words"},{"id":"D","text":"Assume the author made an error"}],"answer":"A","explanation":"Lineation can shape pauses and delayed meaning."},{"question":"Which statement about poetic voice is safest?","options":[{"id":"A","text":"Speaker and poet must always be identical"},{"id":"B","text":"The speaker may be an imagined persona"},{"id":"C","text":"A poem can never use I"},{"id":"D","text":"The reader becomes the author"}],"answer":"B","explanation":"Poets can construct distinct fictional or dramatic voices."},{"question":"Dawn in a poem might suggest:","options":[{"id":"A","text":"Exactly one universal emotion"},{"id":"B","text":"A fixed rhyme scheme"},{"id":"C","text":"A new beginning, depending on context"},{"id":"D","text":"A known publication date"}],"answer":"C","explanation":"Images acquire significance through context and other words, not a universal dictionary of symbols."},{"question":"Why read a poem aloud?","options":[{"id":"A","text":"To discover the book''s ISBN"},{"id":"B","text":"To eliminate all ambiguity"},{"id":"C","text":"To avoid understanding the words"},{"id":"D","text":"To hear rhythm, pauses and sound patterns"}],"answer":"D","explanation":"Reading aloud reveals sound features that silent reading can overlook."}]},{"slug":"oral-literature-and-folktales","code":"GUIDE_SSS1_LIT_T1_ORAL","name":"Oral Literature: Folktales, Proverbs and Performance","body":"# Oral Literature: Folktales, Proverbs and Performance — SSS1 First Term\n\n## Learning aims\nDescribe oral literary forms, interpret original proverbs using context, identify performance techniques and discuss why oral traditions are important to Nigerian cultural history.\n\n## What is oral literature?\nOral literature consists of verbal art shared through speech, song, chanting and performance. It includes folktales, praise poetry, lullabies, chants, riddles and proverbs. A story may change slightly with each performance, and those variations can reveal local values or audience needs. A printed transcription preserves a version of the performance but may omit gesture, tone, audience response and music.\n\n## Folktales\nFolktales can feature animals, humans or supernatural beings and explore cooperation, greed, caution or ingenuity. A story need not have exactly one correct moral. Sometimes a clever character solves a problem; sometimes cleverness harms other people. Explain a moral by referring to actual actions and consequences.\n\n**Original folktale outline:** Two neighbours must share water during a dry week. One hides an extra bucket; the other proposes a schedule. When their remaining water is insufficient, they must decide whether to cooperate. The conflict concerns scarcity, trust and public responsibility. This outline is original classroom material and is not presented as an established Nigerian folktale.\n\n## Proverbs\nA **proverb** is a concise traditional saying communicating practical insight, frequently using figurative language. Invented teaching example: *A borrowed drum still needs a careful hand.* The line could be understood as a warning that responsibility continues even when an item does not belong to us. Its significance depends on a situation: a student borrowing a library book or a musician borrowing an instrument.\n\nBe careful: an invented classroom saying is not an authenticated proverb from a named ethnic community. When discussing an established proverb, verify its wording and cultural context with a reliable speaker or collection.\n\n## Riddles and audience interaction\nA riddle poses a puzzle through indirect clues. A performer may use call-and-response, pacing, repetition, gesture and changes of voice to help an audience follow a tale. The audience may sing, reply or anticipate a familiar refrain. These performative aspects differentiate an oral event from a silent printed text.\n\n## Performance choices\nImagine narrating the two-neighbour tale. A long pause before revealing the hidden bucket may heighten suspense. A repeated chorus may encourage participation; a soft voice could suggest secrecy. None of these details requires copying a copyrighted story.\n\n## Comparing oral and written versions\nA transcription captures words but may flatten timing and vocal emphasis. A performance can make a narrator''s tone audible; a written adaptation can add reflection and precise description. Both are capable of complex artistic meaning.\n\n## Learner exercise\nRetell the original water-sharing outline using a three-sentence opening, a call-and-response phrase and a decision. Then state a theme with evidence. Evaluate whether the message favours cooperation, self-interest or another idea, and explain why.\n\n## Common errors\nTreating oral literature as less sophisticated than books, assigning an invented saying to an ethnic group, or assuming every folktale teaches the same simple moral.","cards":[{"front":"What is oral literature?","back":"Artistic verbal expression passed through speech, song and performance.","difficulty":"medium","sourceKind":"original-literature"},{"front":"Name three oral genres.","back":"For example folktale, proverb, riddle, praise poetry, chant or lullaby.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is call-and-response?","back":"A performance exchange between a leader and audience or chorus.","difficulty":"medium","sourceKind":"original-literature"},{"front":"How does oral performance add meaning?","back":"Through pace, gesture, voice, music, pauses and audience interaction.","difficulty":"medium","sourceKind":"original-literature"},{"front":"What is a proverb?","back":"A concise traditional saying offering insight, often figuratively.","difficulty":"medium","sourceKind":"original-literature"},{"front":"Why verify a proverb''s origin?","back":"To avoid falsely attributing an invented or altered saying to a particular community.","difficulty":"medium","sourceKind":"original-literature"}],"questions":[{"question":"Which is a form of oral literature?","options":[{"id":"A","text":"Folktale told aloud"},{"id":"B","text":"Only a spreadsheet"},{"id":"C","text":"An instruction manual only"},{"id":"D","text":"A plain timetable"}],"answer":"A","explanation":"Folktales may be spoken, sung or performed and belong to oral artistic traditions."},{"question":"A performer asks a phrase and the audience replies together. This is:","options":[{"id":"A","text":"Flashback"},{"id":"B","text":"Call-and-response"},{"id":"C","text":"Footnote"},{"id":"D","text":"Oxymoron"}],"answer":"B","explanation":"Call-and-response is a patterned exchange between leader and audience."},{"question":"Which is a purpose of a proverb?","options":[{"id":"A","text":"To report every event exactly"},{"id":"B","text":"To prove a numerical theorem"},{"id":"C","text":"To communicate compact practical insight"},{"id":"D","text":"To replace all narratives"}],"answer":"C","explanation":"Proverbs condense observations or advice, often through figurative language."},{"question":"Why might a printed folktale differ from an oral performance?","options":[{"id":"A","text":"It always has more narrators"},{"id":"B","text":"It cannot contain a plot"},{"id":"C","text":"It automatically has no theme"},{"id":"D","text":"It may omit gesture, voice and audience participation"}],"answer":"D","explanation":"Performance carries paralinguistic and social elements that print may not capture."},{"question":"A riddle chiefly invites listeners to:","options":[{"id":"A","text":"Infer an answer from clues"},{"id":"B","text":"Memorise a train departure"},{"id":"C","text":"Perform financial auditing"},{"id":"D","text":"Count page numbers"}],"answer":"A","explanation":"Riddles structure an indirect puzzle for an audience to solve."},{"question":"An original classroom saying should be presented as:","options":[{"id":"A","text":"An authenticated proverb from a named group"},{"id":"B","text":"An invented teaching example unless an origin is verified"},{"id":"C","text":"A quotation from an unknown famous poet"},{"id":"D","text":"A historical fact about all communities"}],"answer":"B","explanation":"Attribution must be grounded; invented lines should not be assigned to a culture falsely."},{"question":"Which performance choice may create suspense?","options":[{"id":"A","text":"Reading a catalogue number"},{"id":"B","text":"Ignoring every audience cue"},{"id":"C","text":"A deliberate pause before a revelation"},{"id":"D","text":"Removing all conflict"}],"answer":"C","explanation":"Timing and silence can delay important information and heighten anticipation."},{"question":"Which statement about oral literature is accurate?","options":[{"id":"A","text":"It is automatically inferior to books"},{"id":"B","text":"It has no poetic forms"},{"id":"C","text":"It cannot use metaphor"},{"id":"D","text":"It can be artistically complex and culturally important"}],"answer":"D","explanation":"Oral traditions use expressive language and sophisticated performance techniques."},{"question":"What is a folktale''s theme best inferred from?","options":[{"id":"A","text":"Characters'' actions and consequences"},{"id":"B","text":"Only the storyteller''s clothing"},{"id":"C","text":"Only a printed page count"},{"id":"D","text":"Only the audience size"}],"answer":"A","explanation":"Themes are supported by events, decisions and outcomes in the narrative."},{"question":"A lullaby traditionally belongs to:","options":[{"id":"A","text":"Only government correspondence"},{"id":"B","text":"Oral song traditions"},{"id":"C","text":"Only scientific formulas"},{"id":"D","text":"Only dramatic stage directions"}],"answer":"B","explanation":"Lullabies are sung forms traditionally used for soothing children."},{"question":"How may an audience participate in oral storytelling?","options":[{"id":"A","text":"Only buying a textbook"},{"id":"B","text":"Only taking photographs"},{"id":"C","text":"Responding to repeated phrases or refrains"},{"id":"D","text":"Only acting as a silent examiner"}],"answer":"C","explanation":"Audience responses can be part of the performance''s form and rhythm."},{"question":"Why compare multiple versions of a tale?","options":[{"id":"A","text":"To prove all versions are identical"},{"id":"B","text":"To dismiss oral culture"},{"id":"C","text":"To remove all local meaning"},{"id":"D","text":"To understand variation across contexts and performance choices"}],"answer":"D","explanation":"Comparisons reveal how storytellers adapt a familiar narrative."}]}]'::jsonb)
AS x(slug text,code text,name text,body text,cards jsonb,questions jsonb);
CREATE TEMP TABLE lit_cohorts ON COMMIT DROP AS
SELECT cl.id class_id,cl.name class_name,cl.code class_code,
CASE WHEN cl.code='SSS1-A' THEN 'sss1-a-lit-first-term' ELSE 'sss1-b-lit-first-term' END course_slug
FROM public.classes cl WHERE cl.code IN ('SSS1-A','SSS1-B');
DO $guard$ BEGIN
 IF (SELECT count(*) FROM lit_cohorts)<>2
 THEN RAISE EXCEPTION 'Required SSS1 A/B classes changed; abort'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.subjects WHERE id='1d31ff41-d2f4-48f6-b473-5d2c0d52dcfc' AND name='Literature in English')
 THEN RAISE EXCEPTION 'Literature subject changed; abort'; END IF;
END $guard$;
INSERT INTO public.courses(id,subject_id,class_id,term_id,title,slug,short_description,full_description,difficulty,status,is_free,price,lesson_count,total_duration_hours,published_at,created_at,updated_at)
SELECT gen_random_uuid(),'1d31ff41-d2f4-48f6-b473-5d2c0d52dcfc',co.class_id,'7f7146a4-41d1-4021-a718-f33b59ec1634',
'Literature in English - '||co.class_name||' - First Term',co.course_slug,
'Original SSS1 Literature first-term course with close reading, examples and review questions.',
'Explore prose, drama, poetry, literary devices, appreciation, oral traditions and evidence-based reading through original worked examples and practice.',
'beginner','published',true,0,0,5,now(),now(),now()
FROM lit_cohorts co
WHERE NOT EXISTS (SELECT 1 FROM public.courses c WHERE c.subject_id='1d31ff41-d2f4-48f6-b473-5d2c0d52dcfc' AND c.class_id=co.class_id AND c.term_id='7f7146a4-41d1-4021-a718-f33b59ec1634' AND c.status='published')
ON CONFLICT(slug) DO NOTHING;
INSERT INTO public.course_sections(id,course_id,title,description,order_index,is_active,created_at,updated_at)
SELECT gen_random_uuid(),c.id,'First Term Lessons','Original SSS1 literary study and practice',1,true,now(),now()
FROM public.courses c JOIN lit_cohorts co ON c.class_id=co.class_id AND c.slug=co.course_slug
WHERE NOT EXISTS(SELECT 1 FROM public.course_sections cs WHERE cs.course_id=c.id AND cs.title='First Term Lessons');
INSERT INTO public.topics(id,subject_id,class_id,term_id,name,code,description,learning_objectives,order_index,estimated_hours,is_active,created_at,updated_at)
SELECT gen_random_uuid(),c.subject_id,c.class_id,c.term_id,u.name,u.code,'Original literary-skills unit: '||u.name,
to_jsonb(ARRAY['Describe the literary concept accurately','Interpret an original example using evidence','Demonstrate understanding through practice']),
row_number() over (partition by c.id order by u.code),1,true,now(),now()
FROM public.courses c JOIN lit_cohorts co ON c.class_id=co.class_id AND c.slug=co.course_slug
CROSS JOIN lit_modules u
WHERE NOT EXISTS (SELECT 1 FROM public.topics t WHERE t.class_id=c.class_id AND t.subject_id=c.subject_id AND t.term_id=c.term_id AND lower(trim(t.name))=lower(trim(u.name)))
ON CONFLICT(subject_id,class_id,term_id,code) DO NOTHING;
INSERT INTO public.lessons(id,course_id,section_id,topic_id,title,slug,description,learning_objectives,content_type,written_content,key_points,order_index,is_free,is_published,estimated_minutes,teaching_version,content_quality,created_at,updated_at)
SELECT gen_random_uuid(),c.id,
(SELECT cs.id FROM public.course_sections cs WHERE cs.course_id=c.id AND cs.title='First Term Lessons' ORDER BY cs.id LIMIT 1),
t.id,'SSS1 Literature: '||u.name,u.slug,
'Original, detailed instruction with an invented teaching example and guided textual analysis',
to_jsonb(ARRAY['Recognise the form or device','Explain the example using evidence','Apply the concept independently']),
'text',u.body,to_jsonb(ARRAY['Read for detail before interpreting','Support claims with evidence','Differentiate original practice from past exam papers']),
row_number() over (partition by c.id order by u.code),true,true,35,2,'ready',now(),now()
FROM public.courses c JOIN lit_cohorts co ON c.class_id=co.class_id AND c.slug=co.course_slug
CROSS JOIN lit_modules u
JOIN public.topics t ON t.class_id=c.class_id AND t.subject_id=c.subject_id AND t.term_id=c.term_id AND lower(trim(t.name))=lower(trim(u.name))
WHERE NOT EXISTS(SELECT 1 FROM public.lessons l WHERE l.course_id=c.id AND (l.slug=u.slug OR l.topic_id=t.id))
ON CONFLICT(course_id,slug) DO NOTHING;
INSERT INTO public.flashcards(id,course_id,lesson_id,topic_id,subject_id,title,description,cards,mode,is_public,created_at,updated_at)
SELECT gen_random_uuid(),l.course_id,l.id,l.topic_id,c.subject_id,
'SSS1 Literature: '||u.name,'Recall and explain core literary concepts',u.cards,'curriculum-prebuilt',true,now(),now()
FROM lit_modules u JOIN public.lessons l ON l.slug=u.slug AND l.is_published=true
JOIN public.courses c ON c.id=l.course_id JOIN lit_cohorts co ON c.class_id=co.class_id AND c.slug=co.course_slug
WHERE NOT EXISTS (SELECT 1 FROM public.flashcards f WHERE f.lesson_id=l.id AND f.mode='curriculum-prebuilt' AND f.is_public AND f.created_by IS NULL)
ON CONFLICT DO NOTHING;
INSERT INTO public.questions(id,subject_id,topic_id,class_id,question_type,question_text,options,correct_answer,explanation,difficulty,marks,source,exam_name,tags,is_active,created_at,updated_at)
SELECT gen_random_uuid(),c.subject_id,l.topic_id,c.class_id,'mcq',q.value->>'question',
q.value->'options',to_jsonb(q.value->>'answer'),q.value->>'explanation','medium',1,
'THE GUIDE Original Literature Practice','SSS1 Literature First Term Original Practice',
jsonb_build_array('original-literature','ss1-first-term','lesson:'||l.id::text),true,now(),now()
FROM lit_modules u JOIN public.lessons l ON l.slug=u.slug AND l.is_published=true
JOIN public.courses c ON c.id=l.course_id JOIN lit_cohorts co ON c.class_id=co.class_id AND c.slug=co.course_slug
CROSS JOIN LATERAL jsonb_array_elements(u.questions) q(value)
WHERE jsonb_array_length(q.value->'options')=4
AND NOT EXISTS(SELECT 1 FROM public.questions prior WHERE prior.topic_id=l.topic_id AND prior.question_text=q.value->>'question' AND prior.source='THE GUIDE Original Literature Practice');
UPDATE public.courses c SET lesson_count=(SELECT count(*) FROM public.lessons l WHERE l.course_id=c.id AND l.is_published=true),updated_at=now()
WHERE c.slug IN (SELECT course_slug FROM lit_cohorts);
COMMIT;